  '3660b': [2, 3, 2],
  '3005': [1, 3, 1],
  '3004': [2, 3, 1],
  '3003': [2, 3, 2]
};

const usedCells = new Set();
function p(part, at, colour, turn = 0) {
  const d = PART_DIMS[part] || [1, 1, 1];
  const w = (turn === 90 || turn === 270) ? d[2] : d[0];
  const h = d[1];
  const depth = (turn === 90 || turn === 270) ? d[0] : d[2];
  const [ax, ay, az] = at;
  const pad = (part === '30106') ? 1 : 0;
  for (let x = ax - pad; x < ax + w + pad; x++) {
    for (let y = ay; y < ay + h; y++) {
      for (let z = az - pad; z < az + depth + pad; z++) {
        if (usedCells.has(`${x},${y},${z}`)) return null;
      }
    }
  }
  for (let x = ax - pad; x < ax + w + pad; x++) {
    for (let y = ay; y < ay + h; y++) {
      for (let z = az - pad; z < az + depth + pad; z++) {
        usedCells.add(`${x},${y},${z}`);
      }
    }
  }
  return place({ part, at, colour, turn });
}

script({
  title: 'Imperial I-Class Star Destroyer — Devastator Pursuit',
  description: 'UCS-scale Imperial I-Class Star Destroyer with double-beveled wedge hull, recessed equatorial greeble trenches, terraced superstructure, 8 heavy turbolaser batteries, spherical shield generator domes, 7-nozzle ion engine array, and Tantive IV blockade runner in tractor beam lock.',
  palette: {
    lbg: 'light bluish grey',
    dbg: 'dark bluish grey',
    blk: 'black',
    wht: 'white',
    dred: 'dark red',
    silver: 'flat silver',
    gold: 'pearl gold',
    glow: 'trans light blue',
    tclear: 'trans-clear',
    tred: 'trans red',
    tyel: 'trans yellow',
    hullMix: { mix: ['light bluish grey', 'light bluish grey', 'light bluish grey', 'dark bluish grey'] }
  }
});

// 1. UCS DISPLAY STAND, PLAQUE & MICRO-FLEET
const standOps = [
  // Main base platform
  floor({ at: [-14, 0, -38], size: [28, 66], layers: 2, colour: 'blk', top: 'tile' }),
  floor({ at: [-12, 2, -36], size: [24, 62], layers: 1, colour: 'dbg', top: 'tile' }),
  box({ at: [-8, 3, -16], size: [16, 3, 40], colour: 'blk', texture: 'grille', top: 'tile' }),
  // Imperial emblem & technical grille strips on base
  ...range(-10, 10, 2).map(x => p('2412b', [x, 3, -32], 'silver', 0)),
  ...range(-10, 10, 2).map(x => p('2412b', [x, 3, 22], 'silver', 0)),
  ...range(-14, 20, 4).map(z => p('2412b', [-11, 3, z], 'dbg', 90)),
  ...range(-14, 20, 4).map(z => p('2412b', [10, 3, z], 'dbg', 90)),
  // UCS Specification Plaque at front (-Z)
  box({ at: [-6, 2, -37], size: [12, 3, 4], colour: 'blk', interior: 'solid' }),
  ...range(-6, 6, 2).map(x => p('30363', [x, 5, -37], 'blk', 0)),
  ...range(-5, 5, 2).map(x => p('3069b', [x, 8, -35], 'glow', 0)),
  p('2431', [-2, 8, -34], 'wht', 0),
  // Forward & Aft Support Pylons
  box({ at: [-3, 6, -12], size: [6, 18, 6], colour: 'blk', texture: 'grille', interior: 'solid' }),
  box({ at: [-4, 6, 10], size: [8, 17, 8], colour: 'blk', texture: 'grille', interior: 'solid' }),
  // Tractor Beam emitter ray from ventral bay (z=-22) down to Tantive IV (z=-26)
  ...range(14, 24, 3).map(y => p('3062b', [0, y, -22], 'glow', 0)),
  // Micro-scale Rebel Blockade Runner (Tantive IV) at y=11..14, z=-28..-19
  box({ at: [-1, 6, -25], size: [2, 5, 2], colour: 'tclear', interior: 'solid' }),
  p('98100', [-1, 11, -28], 'dred', 0),
  p('3069b', [-1, 14, -28], 'wht', 0),
  box({ at: [-1, 11, -26], size: [2, 2, 5], colour: 'wht', top: 'tile' }),
  p('3069b', [-1, 13, -25], 'dred', 0),
  box({ at: [-2, 11, -21], size: [4, 3, 3], colour: 'lbg', texture: 'grille' }),
  p('3069b', [-2, 14, -20], 'tyel', 0),
  p('3069b', [0, 14, -20], 'tyel', 0)
];

// Micro TIE Fighter Squadron & Arquitens Light Cruisers
function makeTieFighter(cx, cy, cz) {
  return [
    box({ at: [cx, 0, cz], size: [1, cy, 1], colour: 'tclear', interior: 'solid' }),
    p('87079', [cx - 1, cy, cz - 1], 'blk', 90),
    p('6141', [cx, cy + 1, cz], 'lbg', 0),
    p('87079', [cx + 1, cy, cz - 1], 'blk', 90)
  ];
}
standOps.push(
  ...makeTieFighter(-20, 26, -30),
  ...makeTieFighter(-24, 30, -14),
  ...makeTieFighter(20, 28, -26),
  ...makeTieFighter(24, 32, -10)
);

section('UCS Display Stand and Escort Fleet', standOps);

// 2. LOWER VENTRAL HULL, HANGAR BAY & SOLAR REACTOR DOME
const ventralOps = [];
// Forward nose to widest point: 13 segments of 6 studs (z = -54 to +24)
for (let k = 1; k <= 12; k++) {
  const z0 = -54 + k * 6;
  const hw = 2 * k; // half-width of inner core at this segment
  // Ventral layer 1 (y = 25..27, just under the equatorial plate)
  const w1 = Math.max(2, (hw - 1) * 2);
  // Leave hole for main hangar bay at k=4..7 (z=-30..-6)
  if (k >= 4 && k <= 7) {
    const sideW = Math.max(2, hw - 5);
    ventralOps.push(
      box({ at: [-(hw - 1), 24, z0], size: [sideW, 3, 6], colour: 'lbg', texture: 'grille' }),
      box({ at: [5, 24, z0], size: [sideW, 3, 6], colour: 'lbg', texture: 'grille' }),
      // Recessed hangar ceiling & glowing blue docking bay at y=26
      floor({ at: [-5, 26, z0], size: [10, 6], layers: 1, colour: 'dbg' }),
      p('2431', [-4, 25, z0 + 1], 'glow', 0),
      p('2431', [0, 25, z0 + 1], 'glow', 0),
      p('2412b', [-2, 25, z0 + 3], 'silver', 0),
      p('2412b', [0, 25, z0 + 3], 'silver', 0)
    );
  } else {
    ventralOps.push(
      box({ at: [-(hw - 1), 24, z0], size: [w1, 3, 6], colour: 'lbg', texture: 'grille' })
    );
  }
  // Ventral Wing Bevel plates along outer underside edge at y=24
  ventralOps.push(
    p('54383', [-(2 * k + 1), 26, z0], 'dbg', 0),
    p('54384', [2 * k - 2, 26, z0], 'dbg', 0)
  );
  // Deeper ventral keel tier (y = 22..24) on aft half (k >= 6)
  if (k >= 6) {
    const kw = Math.max(4, (hw - 5) * 2);
    ventralOps.push(
      box({ at: [-(hw - 5), 22, z0], size: [kw, 2, 6], colour: 'dbg', top: 'tile' }),
      p('3660b', [-(hw - 3), 21, z0 + 1], 'lbg', 270),
      p('3660b', [hw - 5, 21, z0 + 1], 'lbg', 90),
      p('3660b', [-(hw - 3), 21, z0 + 3], 'lbg', 270),
      p('3660b', [hw - 5, 21, z0 + 3], 'lbg', 90)
    );
  }
}
// Aft ventral hull (z = +24..+36)
ventralOps.push(
  box({ at: [-20, 24, 24], size: [40, 3, 6], colour: 'lbg', texture: 'grille' }),
  box({ at: [-16, 24, 30], size: [32, 3, 6], colour: 'dbg', texture: 'grille' }),
  // Ventral Solar Ionization Reactor Bulb at z = +8..+16, x = -4..+4, y = 17..22
  p('3961', [-4, 19, 8], 'lbg', 0),
  p('44375b', [-3, 17, 9], 'dbg', 0),
  p('3960', [-2, 15, 10], 'lbg', 0),
  p('4740', [-1, 14, 11], 'glow', 0)
);

section('Lower Ventral Hull and Hangar Bay', ventralOps);

// 3. EQUATORIAL GREEBLE TRENCH & MANDIBLE BEVELS (y = 27..32)
const trenchOps = [];
for (let k = 0; k <= 12; k++) {
  const z0 = -54 + k * 6;
  const xLeftWing = -(3 + 2 * k);
  const xRightWing = 2 * k;
  const coreW = 4 * k;

  // Lower Mandible Wing Lip (y = 27)
  trenchOps.push(
    p('54383', [xLeftWing, 27, z0], 'lbg', 0),
    p('54384', [xRightWing, 27, z0], 'lbg', 0)
  );
  if (coreW > 0) {
    trenchOps.push(
      floor({ at: [-2 * k, 27, z0], size: [coreW, 6], layers: 1, colour: 'lbg' })
    );
  }

  // Recessed Equatorial Trench Core (y = 28..31) — 1 stud inset from outer wing edge
  if (k >= 1) {
    const trenchW = Math.max(2, (2 * k - 1) * 2);
    trenchOps.push(
      box({ at: [-(2 * k - 1), 28, z0], size: [trenchW, 3, 6], colour: 'dbg', texture: 'grille' })
    );
    // Micro-greebling along the recessed trench shelf at xLeftWing+1 and xRightWing+1
    for (let dz = 0; dz < 6; dz += 2) {
      const col = (dz === 2) ? 'glow' : ((dz === 4) ? 'silver' : 'lbg');
      trenchOps.push(
        p('2412b', [-(2 * k), 28, z0 + dz], col, 90),
        p('2412b', [2 * k - 1, 28, z0 + dz], col, 90),
        p('98138', [-(2 * k), 29, z0 + dz], (dz === 2) ? 'tyel' : 'dbg', 0),
        p('98138', [2 * k - 1, 29, z0 + dz], (dz === 2) ? 'tyel' : 'dbg', 0),
        p('3070b', [-(2 * k), 30, z0 + dz + 1], 'lbg', 0),
        p('3070b', [2 * k - 1, 30, z0 + dz + 1], 'lbg', 0)
      );
    }
  } else {
    // Nose tip at k = 0 (z = -54..-48)
    trenchOps.push(
      p('41769a', [-2, 28, -52], 'dbg', 0),
      p('41770a', [0, 28, -52], 'dbg', 0),
      p('41769a', [-2, 29, -52], 'lbg', 0),
      p('41770a', [0, 29, -52], 'lbg', 0),
      p('54200', [-1, 30, -54], 'lbg', 0),
      p('54200', [0, 30, -54], 'lbg', 0)
    );
  }

  // Upper Mandible Wing Lip (y = 31)
  trenchOps.push(
    p('54383', [xLeftWing, 31, z0], 'lbg', 0),
    p('54384', [xRightWing, 31, z0], 'lbg', 0)
  );
  if (coreW > 0) {
    trenchOps.push(
      floor({ at: [-2 * k, 31, z0], size: [coreW, 6], layers: 1, colour: 'lbg', top: 'tile' })
    );
  }
}

// Aft Stern Taper Segments (z = +24..+36, tapering inward toward +Z)
for (let s = 0; s < 2; s++) {
  const z0 = 24 + s * 6;
  const hw = 26 - s * 3; // 26 at z=24..30, 23 at z=30..36
  trenchOps.push(
    p('54384', [-hw, 27, z0], 'lbg', 180),
    p('54383', [hw - 3, 27, z0], 'lbg', 180),
    floor({ at: [-(hw - 3), 27, z0], size: [(hw - 3) * 2, 6], layers: 1, colour: 'lbg' }),
    box({ at: [-(hw - 2), 28, z0], size: [(hw - 2) * 2, 3, 6], colour: 'dbg', texture: 'grille' }),
    p('54384', [-hw, 31, z0], 'lbg', 180),
    p('54383', [hw - 3, 31, z0], 'lbg', 180),
    floor({ at: [-(hw - 3), 31, z0], size: [(hw - 3) * 2, 6], layers: 1, colour: 'lbg', top: 'tile' })
  );
}

section('Equatorial Greeble Trench and Mandible Wings', trenchOps);

// 4. CAMBERED DORSAL MAIN HULL & ARMOR PLATING (y = 32..38)
const dorsalOps = [];
for (let k = 1; k <= 12; k++) {
  const z0 = -54 + k * 6;
  // Layer A (y = 32..34): inset by 2 studs from outer wing
  const hwA = Math.max(2, 2 * k - 1);
  dorsalOps.push(
    p('54383', [-(hwA + 2), 32, z0], 'lbg', 0),
    p('54384', [hwA - 1, 32, z0], 'lbg', 0),
    p('54383', [-(hwA + 1), 33, z0], 'lbg', 0),
    p('54384', [hwA - 2, 33, z0], 'lbg', 0)
  );
  if (hwA > 2) {
    dorsalOps.push(
      floor({ at: [-(hwA - 1), 32, z0], size: [(hwA - 1) * 2, 6], layers: 2, colour: 'lbg', top: 'tile' })
    );
  }
  // Outer armor panel details on y = 32
  for (let dz = 0; dz < 6; dz += 2) {
    dorsalOps.push(
      p('2412b', [-(hwA + 1), 32, z0 + dz], (k % 3 === 0 && dz === 2) ? 'dred' : 'dbg', 90),
      p('2412b', [hwA, 32, z0 + dz], (k % 3 === 0 && dz === 2) ? 'dred' : 'dbg', 90),
      p('61409b', [-(hwA), 34, z0 + dz], 'lbg', 270),
      p('61409b', [hwA - 1, 34, z0 + dz], 'lbg', 90)
    );
  }

  // Layer B (y = 34..36): Cambered inner deck for k >= 2
  if (k >= 2) {
    const hwB = Math.max(2, 2 * k - 4);
    dorsalOps.push(
      p('54383', [-(hwB + 2), 34, z0], 'lbg', 0),
      p('54384', [hwB - 1, 34, z0], 'lbg', 0),
      p('54383', [-(hwB + 1), 35, z0], 'lbg', 0),
      p('54384', [hwB - 2, 35, z0], 'lbg', 0)
    );
    if (hwB > 2) {
      dorsalOps.push(
        floor({ at: [-(hwB - 1), 34, z0], size: [(hwB - 1) * 2, 6], layers: 2, colour: 'lbg', top: 'tile' })
      );
    }
    // Sloped armor transitions & panel lines on Layer B
    for (let dz = 0; dz < 6; dz += 2) {
      dorsalOps.push(
        p('85984', [-(hwB - 1), 36, z0 + dz], 'lbg', 270),
        p('85984', [hwB - 2, 36, z0 + dz], 'lbg', 90),
        p('2412b', [-(hwB - 2), 36, z0 + dz], 'dbg', 90),
        p('2412b', [hwB - 3, 36, z0 + dz], 'dbg', 90)
      );
    }
  }

  // Layer C (y = 36..38): Central Dorsal Spine & Upper Camber for k >= 3
  if (k >= 3) {
    const hwC = Math.max(2, 2 * k - 7);
    dorsalOps.push(
      p('54383', [-(hwC + 2), 36, z0], 'lbg', 0),
      p('54384', [hwC - 1, 36, z0], 'lbg', 0)
    );
    if (hwC > 2) {
      dorsalOps.push(
        floor({ at: [-(hwC - 1), 36, z0], size: [(hwC - 1) * 2, 6], layers: 2, colour: 'lbg', top: 'tile' })
      );
    }
  }

  // Central Dorsal Spine Trench (x = -2..+2) on forward hull (k = 2..6)
  if (k >= 2 && k <= 6) {
    for (let dz = 0; dz < 6; dz += 2) {
      dorsalOps.push(
        p('85984', [-2, 36, z0 + dz], 'lbg', 270),
        p('85984', [1, 36, z0 + dz], 'lbg', 90),
        p('2412b', [-1, 36, z0 + dz], 'silver', 0),
        p('98138', [-1, 37, z0 + dz + 1], 'dbg', 0),
        p('98138', [0, 37, z0 + dz + 1], 'lbg', 0)
      );
    }
  }
}

// Aft Dorsal Hull (z = +24..+36)
for (let s = 0; s < 2; s++) {
  const z0 = 24 + s * 6;
  const hw = 22 - s * 3;
  dorsalOps.push(
    p('54384', [-hw, 32, z0], 'lbg', 180),
    p('54383', [hw - 3, 32, z0], 'lbg', 180),
    floor({ at: [-(hw - 3), 32, z0], size: [(hw - 3) * 2, 6], layers: 3, colour: 'lbg', top: 'tile' }),
    p('54384', [-(hw - 3), 35, z0], 'lbg', 180),
    p('54383', [hw - 6, 35, z0], 'lbg', 180),
    floor({ at: [-(hw - 6), 35, z0], size: [(hw - 6) * 2, 6], layers: 3, colour: 'lbg', top: 'tile' })
  );
}

section('Cambered Dorsal Hull and Armor Plating', dorsalOps);

// 5. TERRACED SUPERSTRUCTURE (CITY-DECK) & 8 HEAVY TURBOLASER BATTERIES (y = 38..50)
const superOps = [];
// Tier 1 Superstructure (y = 38..42, z = -12..+30, 7 segments of 6 studs)
for (let m = 0; m < 7; m++) {
  const z0 = -12 + m * 6;
  const hw1 = Math.min(15, 5 + m * 2);
  superOps.push(
    box({ at: [-(hw1 - 1), 38, z0], size: [(hw1 - 1) * 2, 3, 6], colour: 'dbg', texture: 'grille' }),
    p('54383', [-(hw1 + 1), 41, z0], 'lbg', 0),
    p('54384', [hw1 - 2, 41, z0], 'lbg', 0),
    floor({ at: [-(hw1 - 2), 41, z0], size: [(hw1 - 2) * 2, 6], layers: 1, colour: 'lbg', top: 'tile' })
  );
  // Side trench micro-greebles on Tier 1
  for (let dz = 0; dz < 6; dz += 2) {
    superOps.push(
      p('2412b', [-hw1, 38, z0 + dz], 'silver', 90),
      p('2412b', [hw1 - 1, 38, z0 + dz], 'silver', 90),
      p('98138', [-hw1, 39, z0 + dz], (dz === 2) ? 'glow' : 'lbg', 0),
      p('98138', [hw1 - 1, 39, z0 + dz], (dz === 2) ? 'glow' : 'lbg', 0)
    );
  }
}

// 8 Quad Heavy Turbolaser Batteries (4 Port, 4 Starboard along the dorsal flank)
for (let b = 0; b < 4; b++) {
  const bz = -2 + b * 6;
  const bx = 12 + b * 2;
  // Starboard (-X) and Port (+X) batteries
  superOps.push(
    p('3680', [-(bx + 2), 38, bz], 'dbg', 0),
    p('4032b', [-(bx + 2), 39, bz], 'lbg', 0),
    p('2555', [-(bx + 2), 40, bz], 'dbg', 0),
    p('2555', [-(bx + 1), 40, bz], 'dbg', 0),
    p('3069b', [-(bx + 2), 40, bz + 1], 'lbg', 0),

    p('3680', [bx, 38, bz], 'dbg', 0),
    p('4032b', [bx, 39, bz], 'lbg', 0),
    p('2555', [bx, 40, bz], 'dbg', 0),
    p('2555', [bx + 1, 40, bz], 'dbg', 0),
    p('3069b', [bx, 40, bz + 1], 'lbg', 0)
  );
}

// Tier 2 Superstructure (y = 42..46, z = 0..+28)
for (let m = 0; m < 4; m++) {
  const z0 = 0 + m * 6;
  const hw2 = 4 + m * 2;
  superOps.push(
    box({ at: [-(hw2 - 1), 42, z0], size: [(hw2 - 1) * 2, 3, 6], colour: 'dbg', texture: 'grille' }),
    p('54383', [-(hw2 + 1), 45, z0], 'lbg', 0),
    p('54384', [hw2 - 2, 45, z0], 'lbg', 0),
    floor({ at: [-(hw2 - 2), 45, z0], size: [(hw2 - 2) * 2, 6], layers: 1, colour: 'lbg', top: 'tile' })
  );
  for (let dz = 0; dz < 6; dz += 2) {
    superOps.push(
      p('61409b', [-hw2, 42, z0 + dz], 'lbg', 270),
      p('61409b', [hw2 - 1, 42, z0 + dz], 'lbg', 90),
      p('2412b', [-(hw2 - 2), 46, z0 + dz], 'silver', 0),
      p('2412b', [hw2 - 4, 46, z0 + dz], 'silver', 0)
    );
  }
}

// Tier 3 Superstructure Citadel Base (y = 46..50, z = +10..+26)
const hw3 = 7;
superOps.push(
  box({ at: [-hw3, 46, 10], size: [hw3 * 2, 3, 16], colour: 'dbg', texture: 'grille' }),
  floor({ at: [-(hw3 + 1), 49, 10], size: [(hw3 + 1) * 2, 16], layers: 1, colour: 'lbg', top: 'tile' }),
  // Dorsal City-Deck Greebling on Tier 3
  p('92947', [-5, 50, 12], 'lbg', 0),
  p('4740', [-5, 53, 12], 'silver', 0),
  p('92947', [3, 50, 12], 'lbg', 0),
  p('4740', [3, 53, 12], 'silver', 0),
  p('60477', [-2, 50, 10], 'lbg', 0),
  p('60477', [1, 50, 10], 'lbg', 0),
  p('30363', [-1, 50, 10], 'dbg', 0),
  p('2412b', [-3, 50, 16], 'silver', 0),
