const usedCells = new Set();
function p(part, at, colour, turn = 0) {
  const d = PART_DIMS[part] || [1, 1, 1];
  const w = (turn === 90 || turn === 270) ? d[2] : d[0];
  const h = d[1];
  const depth = (turn === 90 || turn === 270) ? d[0] : d[2];
  const [ax, ay, az] = at;
  const pad = (part === '30106') ? 1 : 0;
  for (let x = ax - pad; x < ax + w + pad; x++) {
    for (let y = ay; y < ay + h; y++) {
      for (let z = az - pad; z < az + depth + pad; z++) {
        if (usedCells.has(`${x},${y},${z}`)) return null;
      }
    }
  }
  for (let x = ax - pad; x < ax + w + pad; x++) {
    for (let y = ay; y < ay + h; y++) {
      for (let z = az - pad; z < az + depth + pad; z++) {
        usedCells.add(`${x},${y},${z}`);
      }
    }
  }
  return place({ part, at, colour, turn });
}

script({
