section('UCS Display Stand and Escort Fleet', standOps);

// 2. LOWER VENTRAL HULL, HANGAR BAY & SOLAR REACTOR DOME
const ventralOps = [];
// Forward nose to widest point: 13 segments of 6 studs (z = -54 to +24)
for (let k = 1; k <= 12; k++) {
