  // Leave hole for main hangar bay at k=4..7 (z=-30..-6)
  if (k >= 4 && k <= 7) {
    const sideW = Math.max(2, hw - 5);
    ventralOps.push(
      box({ at: [-(hw - 1), 24, z0], size: [sideW, 3, 6], colour: 'lbg', texture: 'grille' }),
      box({ at: [5, 24, z0], size: [sideW, 3, 6], colour: 'lbg', texture: 'grille' }),
      // Recessed hangar ceiling & glowing blue docking bay at y=26
      floor({ at: [-5, 26, z0], size: [10, 6], layers: 1, colour: 'dbg' }),
      p('2431', [-4, 25, z0 + 1], 'glow', 0),
      p('2431', [0, 25, z0 + 1], 'glow', 0),
      p('2412b', [-2, 25, z0 + 3], 'silver', 0),
      p('2412b', [0, 25, z0 + 3], 'silver', 0)
    );
  } else {
    ventralOps.push(
      box({ at: [-(hw - 1), 24, z0], size: [w1, 3, 6], colour: 'lbg', texture: 'grille' })
    );
  }
  // Ventral Wing Bevel plates along outer underside edge at y=24
  ventralOps.push(
    p('54383', [-(2 * k + 1), 26, z0], 'dbg', 0),
